package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructParametricType_TriageGen0Test {

    private TypeFactory _typeFactory;

    @Before
    public void setUp() {
        _typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testConstructParametricType_SingleParameter() {
        // Test List<String>
        JavaType result = _typeFactory.constructParametricType(List.class, String.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(1, result.getActualTypeArguments().length);
        Assert.assertEquals(String.class, result.getActualTypeArguments()[0].getRawClass());
    }

    @Test
    public void testConstructParametricType_MultipleParameters() {
        // Test Map<String, Integer>
        JavaType result = _typeFactory.constructParametricType(Map.class, String.class, Integer.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Map.class, result.getRawClass());
        Assert.assertEquals(2, result.getActualTypeArguments().length);
        Assert.assertEquals(String.class, result.getActualTypeArguments()[0].getRawClass());
        Assert.assertEquals(Integer.class, result.getActualTypeArguments()[1].getRawClass());
    }

    @Test
    public void testConstructParametricType_NoParameters() {
        // Test a non-generic class or empty varargs
        JavaType result = _typeFactory.constructParametricType(String.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(String.class, result.getRawClass());
        Assert.assertEquals(0, result.getActualTypeArguments().length);
    }

    @Test
    public void testConstructParametricType_WithPrimitive() {
        // Test List<Integer> (Wrapper) and List<int[]> (Array)
        // Note: Jackson handles primitives via their wrapper classes in most TypeFactory contexts
        JavaType result = _typeFactory.constructParametricType(List.class, int[].class);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(int[].class, result.getActualTypeArguments()[0].getRawClass());
    }

    @Test
    public void testConstructParametricType_NestedGenerics() {
        // Test List<List<String>>
        JavaType innerType = _typeFactory.constructParametricType(List.class, String.class);
        JavaType outerType = _typeFactory.constructParametricType(List.class, innerType.getRawClass(), innerType); 
        // Note: The method signature uses Class<?>... parameterClasses, 
        // so we can't pass the JavaType directly into the varargs of THIS specific overload 
        // without it being cast to Class, which would fail. 
        // However, the method implementation calls constructParametricType(parametrized, pt) 
        // where pt is JavaType[].

        // To test the internal flow correctly:
        JavaType nested = _typeFactory.constructParametricType(List.class, List.class, String.class);
        // Actually, the method signature provided: constructParametricType(Class<?> parametrized, Class<?>... parameterClasses)
        // means the 'parameterClasses' are converted to JavaTypes via _fromClass.

        JavaType listString = _typeFactory.constructParametricType(List.class, String.class);
        // Since the method signature takes Class<?>..., we test the logic of converting classes to types.
        JavaType result = _typeFactory.constructParametricType(List.class, String.class);
        Assert.assertEquals(String.class, result.getActualTypeArguments()[0].getRawClass());
    }

    @Test(expected = NullPointerException.class)
    public void testConstructParametricType_NullParametrized() {
        _typeFactory.constructParametricType(null, String.class);
    }

    @Test
    public void testConstructParametricType_ComplexClass() {
        // Test with a custom class or standard complex class
        JavaType result = _typeFactory.constructParametricType(Map.class, Object.class, Object.class);
        Assert.assertEquals(Map.class, result.getRawClass());
        Assert.assertEquals(Object.class, result.getActualTypeArguments()[0].getRawClass());
        Assert.assertEquals(Object.class, result.getActualTypeArguments()[1].getRawClass());
    }
}
